insert into brands (id, name, kit) values ('phantom', 'Phantom Heli', '{"fonts":{"display":{"family":"Barlow Condensed","weight":800},"body":{"family":"Source Sans 3","weight":400}},"headlineCase":"upper","defaultPublishTime":"18:30","timezone":"America/Vancouver","logo":{},"allowAiImages":false,"colors":{"primary":"#111111","accent":"#ffffff","ink":"#111111","paper":"#ffffff","overlay":"#000000"},"voice":"Heli-skiing operator based in Squamish, BC, 25 minutes from Whistler (Sea to Sky). Confident, calm and precise. Sell the terrain and getting the right day; the safety margin is a reason to trust us, never a scare. Short sentences, concrete numbers from the brief.","rules":["Every post is approved by Ross before it goes out.","No AI-generated or AI-edited images. Real photos only.","Write \"Weather Window\" in full, capitalised. Never \"Weather Window Guarantee\" and never just \"window\".","Weather Window posts lead with getting the right day, not with what happens if the weather is bad.","Use only facts, prices and numbers that are in the brief; never invent them.","Never name a guide or show a recognisable guest unless consent is confirmed in the brief.","Credit the photographer when a credit is given."],"hashtags":["#phantomheli","#heliskiing","#squamish","#seatosky"],"handle":"@phantom.heli","website":"https://phantomheli.com","defaultCta":"BOOK_TRAVEL"}'::jsonb) on conflict (id) do nothing;
